        toks = [self.subject_prefix + t for t in self._tokens(subject)] + self._tokens(body)
        if self.drop_tokens:
            drop = set(self.drop_tokens)
            toks = [t for t in toks if t not in drop]
        return toks


def make_analyzer(cfg, drop_tokens=()):
